136	import React from "react";
137	
138	import type { Abi, Address } from "viem";
139	
140	import { Periods } from "consts/periods";
141	
142	import { DisputeDetailsQuery } from "src/graphql/graphql";
143	
144	import type { DisputeKits } from "./disputeKits";
145	
146	/** Props for Overview extra info (ex. token gate display) */
147	export interface OverviewExtraInfoProps {
148	  disputeId: string;
149	  currentRoundIndex: number;
150	}
151	
152	export interface DisputeKitVotingProps {
153	  arbitrable: Address;
154	  /** Called to toggle popup, maybe change to callback? to be called after an action is completed */
155	  setIsOpen: (val: boolean) => void;
156	  disputeKitId: DisputeKits;
157	  dispute: DisputeDetailsQuery["dispute"];
158	  currentPeriodIndex: Periods;
159	}
160	
161	export interface DisputeKitAppealProps {
162	  isAppealMiniGuideOpen: boolean;
163	  toggleAppealMiniGuide: () => void;
164	  disputeKitId: DisputeKits;
165	}
166	
167	export enum Group {
168	  Voting = "Voting",
169	  Eligibility = "Eligibility",
170	}
171	
172	/** A single feature, grouped into categories. has to be atomic.
173	 * For gated, we split them into atomic erc20 and erc1155 */
174	export enum Features {
175	  ShieldedVote = "shieldedVote",
176	  ClassicVote = "classicVote",
177	  UniversityVote = "universityVote",
178	  ClassicEligibility = "classicEligibility",
179	  GatedErc20 = "gatedErc20",
180	  GatedErc1155 = "gatedErc1155",
181	  ArgentinaConsumerProtection = "argentinaConsumerProtection",
182	}
183	
184	/** Group of features (like radio buttons per category) */
185	export type FeatureGroups = Record<Group, Features[]>;
186	
187	export interface DisputeKitConfig<TAbi extends Abi = Abi> {
188	  id: DisputeKits;
189	  displayName: string;
190	  address: Address;
191	  OverviewExtraInfo?: React.FC<OverviewExtraInfoProps>;
192	  // Rendering just the Voting component allows us to let
193	  // DisputeKit Voting component handle the separate flows of Vote, Reveal, Commit.
194	  VotingComponent: React.FC<DisputeKitVotingProps>;
195	  AppealComponent: React.FC<DisputeKitAppealProps>;
196	  disputeKitAbi: TAbi;
197	  hasAutomaticVoteReveal: boolean;
198	  /**
199	   * The feature sets this kit supports.
200	   * Each array represents a valid configuration, and has to be 1:1,
201	   * if either subset matches the selected feature array this dispute kit is selected.
202	   * each array is a unique match, for multiple combinations, add more arrays.
203	   */
204	  featureSets: Features[][];
205	}
206	import { DisputeKitConfig, DisputeKits } from "src/dispute-kits";
207	
208	import { isProductionDeployment } from "../consts/index";
209	
210	import { DisputeKitDataMap } from "./prepareArbitratorExtradata";
211	import { DISPUTE_KIT_REGISTRY } from "./registry";
212	import { FeatureGroups, Features, Group } from "./types";
213	
214	// groups
215	// withing a group only one feature can be selected, we deselect the other one when a new one is selected
216	// we don't use these directly in here for utils because these need to be filtered based on court selection.
217	// NOTE: a feature cannot appear in more than one Group
218	// DEV: the order of features in array , determine the order the radios appear on UI
219	export const featureGroups: FeatureGroups = {
220	  [Group.Voting]: [Features.ClassicVote, Features.ShieldedVote, Features.UniversityVote],
221	  [Group.Eligibility]: [
222	    Features.ClassicEligibility,
223	    Features.GatedErc20,
224	    Features.GatedErc1155,
225	    Features.ArgentinaConsumerProtection,
226	  ],
227	};
228	
229	// excluded on mainnet, we can later update it to an array if we want to have more deployment specific kits
230	const UNIVERSITY_DISPUTE_KIT_ID = DisputeKits.ClassicUniversity;
231	
232	const disputeKits = Object.values(DISPUTE_KIT_REGISTRY);
233	/**
234	 * Dispute kits available for the current deployment.
235	 * University DK is excluded on mainnet.
236	 */
237	export const getDisputeKitsForDeployment = (): DisputeKitConfig[] =>
238	  isProductionDeployment() ? disputeKits.filter((kit) => kit.id !== UNIVERSITY_DISPUTE_KIT_ID) : disputeKits;
239	
240	/**
241	 * Feature groups for the current deployment.
242	 * University vote is excluded on mainnet.
243	 */
244	export const getFeatureGroupsForDeployment = (): FeatureGroups =>
245	  isProductionDeployment()
246	    ? {
247	        ...featureGroups,
248	        [Group.Voting]: featureGroups[Group.Voting].filter((f) => f !== Features.UniversityVote),
249	      }
250	    : featureGroups;
251	
252	export function resolveInitialFeatureSet(kit: DisputeKitConfig, disputeKitData?: DisputeKitDataMap[DisputeKits]) {
253	  switch (kit.id) {
254	    case DisputeKits.Classic:
255	    case DisputeKits.Shutter:
256	    case DisputeKits.ArgentinaConsumerProtection:
257	    case DisputeKits.ClassicUniversity:
258	      return kit.featureSets[0];
259	    case DisputeKits.Gated:
260	    case DisputeKits.GatedShutter: {
261	      const isERC1155 = disputeKitData?.isERC1155;
262	      return (
263	        kit.featureSets.find((set) =>
264	          isERC1155 ? set.includes(Features.GatedErc1155) : set.includes(Features.GatedErc20)
265	        ) ?? kit.featureSets[0]
266	      );
267	    }
268	    default: {
269	      // this is an exhaustive type check,
270	      // so we get a type error if a disputeKit is not handled in above switch
271	      const _exhaustive = kit.id satisfies never;
272	      return _exhaustive;
273	    }
274	  }
275	}
276	
277	/** Canonical string for a feature set (order-independent) */
278	function normalize(features: Features[]): string {
279	  return [...features].sort().join("|");
280	}
281	
282	/** Check if `a` is exactly the same as `b` (order-insensitive) */
283	function arraysEqual(a: Features[], b: Features[]): boolean {
284	  return normalize(a) === normalize(b);
285	}
286	
287	/**
288	 * Toggle a feature, ensuring radio behavior per group
289	 * @returns the updated selected features array
290	 */
291	export function toggleFeature(selected: Features[], feature: Features, groups: FeatureGroups): Features[] {
292	  const group = Object.entries(groups).find(([_, feats]) => feats.includes(feature));
293	  if (!group) return selected; // not found in any group
294	  const [_, features] = group; // <= this is the group we are making selection in currently
295	
296	  // Remove any feature from this group
297	  const withoutGroup = selected.filter((f) => !features.includes(f));
298	
299	  // If it was already selected => deselect
300	  if (selected.includes(feature)) {
301	    return withoutGroup;
302	  }
303	
304	  // Otherwise => select this one
305	  return [...withoutGroup, feature];
306	}
307	
308	/**
309	 * Find dispute kits that match the given selection
310	 */
311	export function findMatchingKits(selected: Features[], kits: DisputeKitConfig[]): DisputeKitConfig[] {
312	  return kits.filter((kit) =>
313	    kit.featureSets.some(
314	      (set) => arraysEqual(set, selected) // strict exact match
315	    )
316	  );
317	}
318	
319	/**
320	 * Ensures that the current selection of features is always in a valid state.
321	 * We use this just to make sure we don't accidently allow user to select an invalid state in handleToggle
322	 *
323	 * "Valid" means:
324	 *   - Either matches at least one dispute kit fully, OR
325	 *   - Could still be completed into a valid kit (prefix of a valid set).
326	 *
327	 * If the selection is invalid:
328	 *   1. Try removing one conflicting group to recover validity.
329	 *   2. If nothing works, fallback to keeping only the last clicked feature.
330	 *
331	 * @returns  A corrected selection that is guaranteed to be valid.
332	 */
333	export function ensureValidSmart(selected: Features[], groups: FeatureGroups, kits: DisputeKitConfig[]): Features[] {
334	  // --- Helper: checks if a candidate is valid or could still become valid ---
335	  function isValidOrPrefix(candidate: Features[]): boolean {
336	    return (
337	      findMatchingKits(candidate, kits).length > 0 ||
338	      kits.some((kit) =>
339	        kit.featureSets.some(
340	          (set) => candidate.every((f) => set.includes(f)) // prefix check
341	        )
342	      )
343	    );
344	  }
345	
346	  // --- Case 1: Current selection is already valid ---
347	  if (isValidOrPrefix(selected)) {
348	    return selected;
349	  }
350	
351	  // --- Case 2: Try fixing by removing one group at a time ---
352	  for (const [_, features] of Object.entries(groups)) {
353	    const withoutGroup = selected.filter((f) => !features.includes(f));
354	    if (isValidOrPrefix(withoutGroup)) {
355	      return withoutGroup;
356	    }
357	  }
358	
359	  // --- Case 3: Fallback to only the last picked feature ---
360	  return selected.length > 0 ? [selected[selected.length - 1]] : [];
361	}
362	
363	// Checks if the candidate if selected, can still lead to a match
364	function canStillLeadToMatch(candidate: Features[], kits: DisputeKitConfig[]): boolean {
365	  return kits.some((kit) =>
366	    kit.featureSets.some((set) =>
367	      // candidate must be subset of this set
368	      candidate.every((f) => set.includes(f))
369	    )
370	  );
371	}
372	
373	/**
374	 * Compute which features should be disabled,
375	 * given the current selection.
376	 */
377	export function getDisabledOptions(
378	  selected: Features[],
379	  groups: FeatureGroups,
380	  kits: DisputeKitConfig[]
381	): Set<Features> {
382	  const disabled = new Set<Features>();
383	
384	  // If nothing is selected => allow all
385	  if (selected.length === 0) {
386	    return disabled;
387	  }
388	
389	  for (const [_, features] of Object.entries(groups)) {
390	    for (const feature of features) {
391	      const candidate = toggleFeature(selected, feature, groups);
392	
393	      // Instead of only checking full matches:
394	      const valid = findMatchingKits(candidate, kits).length > 0 || canStillLeadToMatch(candidate, kits);
395	
396	      if (!valid) {
397	        disabled.add(feature);
398	      }
399	    }
400	  }
401	
402	  return disabled;
403	}
404	
405	/**
406	 * Features that are visible for a given court,
407	 * based only on the kits that court supports.
408	 */
409	export function getVisibleFeaturesForCourt(
410	  supportedKits: number[],
411	  allKits: DisputeKitConfig[],
412	  groups: FeatureGroups
413	): FeatureGroups {
414	  // Get supported kits for this court
415	  const filteredKits = allKits.filter((kit) => supportedKits.includes(kit.id));
416	
417	  // Gather all features that appear in these kits
418	  const visible = new Set<Features>();
419	  for (const kit of filteredKits) {
420	    for (const set of kit.featureSets) {
421	      set.forEach((f) => visible.add(f));
422	    }
423	  }
424	
425	  // Filter groups => only keep features that are visible
426	  // This is assuming that each kit supports at least one Feature from each Group,
427	  // and a court has at least one matching kit. which holds true for current kits.
428	  const filteredGroups: FeatureGroups = {
429	    [Group.Voting]: groups[Group.Voting].filter((f) => visible.has(f)),
430	    [Group.Eligibility]: groups[Group.Eligibility].filter((f) => visible.has(f)),
431	  };
432	  return filteredGroups;
433	}

