     1	import { Abi, ContractFunctionName, WriteContractParameters } from "viem";
     2	
     3	export type ActionTx<TAbi extends Abi, TFn extends ContractFunctionName<TAbi>> = WriteContractParameters<TAbi, TFn>;
     4	
     5	export interface ActionBuilder<TParams, TContext, TDeps, TAbi extends Abi, TFn extends ContractFunctionName<TAbi>> {
     6	  /**
     7	   * Builder-level dependency defaults.
     8	   *
     9	   * Allows a specific builder to:
    10	   * - Provide defaults for dependencies it uniquely requires
    11	   *   (e.g. an `encrypt` helper used only by shutter builders)
    12	   * - Override any global default dependency if necessary
    13	   *   (e.g. a specialized storage implementation)
    14	   *
    15	   * These dependencies are shallow-merged with the global defaults
    16	   * and any call-site overrides at build time.
    17	   *
    18	   * Call-site overrides passed to `build(...)` always take precedence.
    19	   */
    20	  builderDeps?: Partial<TDeps>;
    21	  build(params: TParams, context: TContext, deps: TDeps): Promise<ActionTx<TAbi, TFn>>;
    22	}
    23	
    24	/**
    25	 * Typed action builder factory.
    26	 *
    27	 * This helper fixes the `params`, `context`, and `deps` types for a family of
    28	 * action builders, so individual builders only need to specify the contract ABI
    29	 * and function name, which also inferred from return object of builder.build.
    30	 *
    31	 * Dependency resolution happens at build time via a shallow merge, in the
    32	 * following order (later entries take precedence):
    33	 *
    34	 * 1. Global default dependencies provided to this factory
    35	 * 2. Builder-level default dependencies (`builder.builderDeps`)
    36	 * 3. Call-site dependency overrides passed to `build(...)`
    37	 *
    38	 * This allows:
    39	 * - Shared builder dependencies to be defined once globally
    40	 * - Individual builders to declare or override defaults for their own needs
    41	 * - Callers (e.g. tests) to selectively override any dependency
    42	 *
    43	 * The resolved dependency object is guaranteed (at the type level) to satisfy
    44	 * `TDeps` and is passed to the builder implementation as a fully populated
    45	 * dependency set.
    46	 *
    47	 * @typeParam TParams   Parameters coming from the caller (usually UI input)
    48	 * @typeParam TContext  Execution context (e.g. chain, account)
    49	 * @typeParam TDeps     Dependency set for the builder (storage, etc.)
    50	 *
    51	 * @param defaultDeps   Global default dependencies shared by all builders
    52	 *
    53	 * @returns A function that accepts a builder definition and returns an object
    54	 *          exposing a `build` function with dependency resolution applied.
    55	 */
    56	export function defineActionBuilder<TParams, TContext, TDeps extends object>(defaultDeps: TDeps) {
    57	  return function <TAbi extends Abi, TFn extends ContractFunctionName<TAbi>>(
    58	    builder: ActionBuilder<TParams, TContext, TDeps, TAbi, TFn>
    59	  ) {
    60	    return {
    61	      build(params: TParams, context: TContext, overrideDeps?: Partial<TDeps>) {
    62	        const resolvedDeps = {
    63	          ...defaultDeps,
    64	          ...builder?.builderDeps,
    65	          ...overrideDeps,
    66	        } satisfies TDeps;
    67	
    68	        return builder.build(params, context, resolvedDeps);
    69	      },
    70	    };
    71	  };
    72	}
