    10	 *
    11	 * @remarks Never throws. Failures are logged as warnings.
    12	 * @todo Make this throwable for commit types where brute-forcing is not possible.
    13	 */
    14	export function storeCommitData(key: string, data: CommitData): void {
    15	  const parsedData: StoredCommitData = {
    16	    salt: data.salt.toString(),
    17	    choice: data.choice.toString(),
    18	    justification: data.justification,
    19	  };
    20	
    21	  try {
    22	    localStorage.setItem(key, JSON.stringify(parsedData));
    23	  } catch (err) {
    24	    console.warn(`storeCommitData: Failed to persist commit data for key "${key}"`, err);
    25	  }
    26	}
    27	
    28	/**
    29	 * Retrieves commit data from localStorage.
    30	 * Is allowed to fail, since we can bruteforce the choice
    31	 *
    32	 * @param key Unique identifier that the data was stored with.
    33	 * See {@link module:getVoteKey} for details on key construction.
    34	 *
    35	 * @remarks Never throws. Failures are logged as warnings.
    36	 * @todo Make this throwable for commit types where brute-forcing is not possible.
    37	 */
    38	export function restoreCommitData(key: string): CommitData | undefined {
    39	  const raw = localStorage.getItem(key);
    40	  if (!raw) return undefined;
    41	
    42	  try {
    43	    const storedData = JSON.parse(raw) as StoredCommitData;
    44	
    45	    return {
    46	      salt: BigInt(storedData.salt),
    47	      choice: BigInt(storedData.choice),
    48	      justification: storedData.justification,
    49	    };
    50	  } catch (err) {
    51	    if (err instanceof Error) {
    52	      console.warn("restoreCommitData: Failed to retrieve choice data from localStorage.", err.message);
    53	    }
    54	
    55	    return undefined;
    56	  }
    57	}
    58	
    59	export function removeCommitData(key: string): void {
