     1	import { generateSalt } from "utils/crypto/generateSalt";
     2	
     3	import { restoreCommitData } from "../helpers/storage";
     4	import { getVoteKey } from "../helpers/storage/getVoteKey";
     5	
     6	import { bruteForceChoice } from "./helpers/bruteForceChoice";
     7	import { ResolveRevealContext, ResolveRevealParams, RevealParams } from "./params";
     8	
     9	/**
    10	 * Resolves all inputs required for a Reveal Action builder.
    11	 *
    12	 * This function ensures that `salt`, `choice`, and `justification` are available,
    13	 * either by retrieving them from local storage or by regenerating them if missing.
    14	 *
    15	 * Behavior:
    16	 * 1. Attempts to restore stored commit data for the given dispute, round, and vote IDs.
    17	 * 2. Uses the provided `justification` if present, else falls back to stored value, else empty string.
    18	 * 3. If no stored data is found:
    19	 *    - Regenerates the salt using `generateSalt` and a signing account.
    20	 *    - Recovers the original vote `choice` by brute-forcing against the commit using `bruteForceChoice`.
    21	 *
    22	 * @param params  Parameters for resolving reveal, including disputeId, roundIndex, voteIds, and optional justification.
    23	 * @param context Execution context including signing account, answers array, commit hash, and helper functions.
    24	 *
    25	 * @returns Fully populated {@link RevealParams} containing:
    26	 * - `salt` as a `bigint`
    27	 * - `choice` as a `bigint`
    28	 * - `justification` as a string
    29	 *
    30	 * @throws Will throw an error if:
    31	 * - Salt regeneration is required but no signing account is available.
    32	 * - Choice cannot be recovered due to missing answers or commit.
    33	 */
    34	export async function resolveRevealInputs(
    35	  params: ResolveRevealParams,
    36	  context: ResolveRevealContext
    37	): Promise<RevealParams> {
    38	  const key = getVoteKey(params.disputeId, params.roundIndex, params.voteIds);
    39	  const stored = restoreCommitData(key);
    40	
    41	  const justification = params.justification ?? stored?.justification ?? "";
    42	
    43	  if (stored) return { ...params, ...stored, justification };
    44	
    45	  // regenerate salt
    46	  if (!context.signingAccount && !context.generateSigningAccount) {
    47	    throw new Error("Cannot regenerate salt: no signing account available");
    48	  }
    49	
    50	  const signingAccount = context.signingAccount ?? (await context.generateSigningAccount!());
    51	
    52	  if (!signingAccount) {
    53	    throw new Error("Cannot regenerate salt: unable to generate signing account.");
    54	  }
    55	  const salt = await generateSalt(signingAccount, key);
    56	
    57	  if (!context.answers || !context.commit) {
    58	    throw new Error("Cannot retrieve choice: answers and commit not available");
    59	  }
    60	
    61	  const choice = bruteForceChoice(salt, context.answers, context.commit);
    62	
    63	  return {
    64	    ...params,
    65	    salt: BigInt(salt),
    66	    choice,
    67	    justification,
    68	  };
    69	}
=== reveal/helpers/bruteForceChoice.ts
     1	import { Hex } from "viem";
     2	
     3	import { Answer } from "@kleros/kleros-sdk";
     4	
     5	import { Bytes32Hash, hashVote } from "utils/crypto/hashVote";
     6	/**
     7	 * Attempts to recover a user's original vote choice from a salted commit.
     8	 *
     9	 * This function "brute-forces" the choice by hashing each candidate answer
    10	 * with the provided salt and comparing it against the given commit.
    11	 * If the commit matches one of the candidates, the corresponding choice ID is returned.
    12	 *
    13	 * When a dispute has no answers, a default "Refuse To Arbitrate" answer is added
    14	 * so that even empty disputes can be checked.
    15	 *
    16	 * @param salt    The deterministic salt used in the original commit
    17	 * @param answers Array of possible answers in the dispute. See {@link Answer}
    18	 * @param commit  The hexadecimal commit string to compare against.
    19	 *
    20	 * @returns The `id` of the matching answer (as a bigint) if found.
    21	 *
    22	 * @throws Will throw an error if no matching choice is found.
    23	 */
    24	export const bruteForceChoice = (salt: Hex, answers: Answer[], commit: Bytes32Hash) => {
    25	  // when dispute is invalid, just add RFA to the answers array
    26	  const candidates =
    27	    answers?.length > 0
    28	      ? answers
    29	      : [{ id: "0x0", title: "Refuse To Arbitrate", description: "Refuse To Arbitrate" } as Answer];
    30	
    31	  const { found, choice } = candidates.reduce<{ found: boolean; choice: bigint }>(
    32	    (acc, answer) => {
    33	      if (acc.found) return acc;
    34	
    35	      const innerCommit = hashVote(BigInt(answer.id), BigInt(salt));
    36	
    37	      return innerCommit === commit ? { found: true, choice: BigInt(answer.id) } : acc;
    38	    },
    39	    { found: false, choice: BigInt(-1) }
    40	  );
    41	
    42	  if (!found) {
    43	    throw new Error("Unable to retrieve choice.");
    44	  }
    45	
    46	  return choice;
    47	};
