     1	import { useMutation, useQueryClient } from "@tanstack/react-query";
     2	import { useWalletClient, usePublicClient, useAccount } from "wagmi";
     3	
     4	import { executeCommit } from "actions/commit/execute";
     5	import type { CommitParams } from "actions/commit/params";
     6	import { getVoteKey } from "actions/helpers/storage/getVoteKey";
     7	
     8	import { generateSalt } from "utils/crypto/generateSalt";
     9	import { PartialBy } from "utils/types";
    10	import { errorToast, wrapWithToast } from "utils/wrapWithToast";
    11	
    12	import { isUndefined } from "src/utils";
    13	
    14	import useSigningAccount from "./useSigningAccount";
    15	
    16	type CommitVoteParams = PartialBy<CommitParams, "salt">;
    17	
    18	export function useCastCommit(onSuccess?: () => void) {
    19	  const queryClient = useQueryClient();
    20	
    21	  const { data: walletClient } = useWalletClient();
    22	  const publicClient = usePublicClient();
    23	  const { signingAccount: _signingAccount, generateSigningAccount } = useSigningAccount();
    24	  const { address: account, chain } = useAccount();
    25	
    26	  return useMutation({
    27	    mutationFn: async (params: CommitVoteParams) => {
    28	      if (isUndefined(account)) {
    29	        throw new Error("Account not defined. Is the wallet connected?");
    30	      }
    31	      if (isUndefined(chain)) {
    32	        throw new Error("Chain not defined. Is the wallet connected?");
    33	      }
    34	
    35	      if (isUndefined(walletClient)) {
    36	        throw new Error("WalletClient not defined. Is the wallet connected?");
    37	      }
    38	
    39	      if (isUndefined(publicClient)) {
    40	        throw new Error("PublicClient not defined. Is the wallet connected?");
    41	      }
    42	
    43	      // ensure we have a signing account
    44	      const signingAccount = _signingAccount ?? (await generateSigningAccount());
    45	      if (!signingAccount) throw new Error("No signing account available");
    46	
    47	      // generate salt
    48	      const message = getVoteKey(params.disputeId, params.roundIndex, params.voteIds);
    49	      const salt = await generateSalt(signingAccount, message);
    50	
    51	      const executeParams: CommitParams = { ...params, salt: BigInt(salt) };
    52	      const executeTxn = () => executeCommit(executeParams, { chain, account, walletClient });
    53	
    54	      const result = await wrapWithToast(executeTxn, publicClient);
    55	
    56	      return result;
    57	    },
    58	    onSuccess: (res) => {
    59	      if (!res.status) return;
    60	      onSuccess?.();
    61	      queryClient.invalidateQueries({ queryKey: ["useDrawQuery"] });
    62	    },
    63	    onError: (err: unknown) => {
    64	      console.error(err);
    65	      if (err instanceof Error) {
    66	        errorToast(err.message);
    67	      }
    68	    },
    69	  });
    70	}
