    47	    !isUndefined(disputeKitInfo) &&
    48	    !isUndefined(disputeKitAddress) &&
    49	    !isUndefined(roundId) &&
    50	    !isUndefined(voteId) &&
    51	    !isUndefined(id);
    52	
