 66	  const [pendingOption, setPendingOption] = useState<bigint | undefined>(undefined);
 67	
 68	  const updatedRTA = useMemo(() => {
 69	    const RTAFromTemplate = disputeDetails?.answers?.find((answer) => BigInt(answer.id) === BigInt(0));
 70	    if (!RTAFromTemplate) return RefuseToArbitrateAnswer;
 71	    return RTAFromTemplate;
 72	  }, [disputeDetails]);
 73	
