    12	
    13	import { graphql } from "src/graphql";
    14	
    15	import { klerosCoreAddress } from "../contracts/generated";
    16	
    17	import { useDisputeDetailsQuery } from "./useDisputeDetailsQuery";
    18	
    19	const disputeTemplateQuery = graphql(`
    20	  query DisputeTemplate($id: ID!) {
    21	    disputeTemplate(id: $id) {
    22	      id
    23	      templateTag
    24	      templateData
    25	      templateDataMappings
    26	    }
    27	  }
    28	`);
    29	
    30	export const usePopulatedDisputeData = (disputeID?: string, arbitrableAddress?: Address) => {
    31	  const { data: disputeData } = useDisputeDetailsQuery(disputeID);
    32	  const { graphqlBatcher } = useGraphqlBatcher();
    33	  const isEnabled =
    34	    !isUndefined(disputeID) &&
    35	    !isUndefined(disputeData) &&
    36	    !isUndefined(disputeData?.dispute) &&
    37	    !isUndefined(disputeData.dispute?.arbitrableChainId) &&
    38	    !isUndefined(disputeData.dispute?.templateId);
    39	
    40	  return useQuery<DisputeDetails>({
    41	    queryKey: [`DisputeTemplate`, disputeID],
    42	    enabled: isEnabled,
    43	    staleTime: Infinity,
    44	    queryFn: async () => {
    45	      if (isEnabled) {
    46	        try {
    47	          const { disputeTemplate } = await graphqlBatcher.fetch({
    48	            id: crypto.randomUUID(),
    49	            document: disputeTemplateQuery,
    50	            variables: { id: disputeData.dispute!.templateId!.toString() },
    51	            isDisputeTemplate: true,
    52	            chainId: DEFAULT_CHAIN.id,
    53	          });
    54	
    55	          const templateData = disputeTemplate?.templateData;
    56	          const dataMappings = disputeTemplate?.templateDataMappings;
    57	
    58	          const initialContext = {
    59	            // Matching the variable name to DisputeRequest
    60	            // eslint-disable-next-line max-len
    61	            // https://github.com/kleros/kleros-v2/blob/592243f52d57e1540206c06afdbdac0d77311106/contracts/src/arbitration/interfaces/IArbitrableV2.sol#L21
    62	            arbitrator: klerosCoreAddress[DEFAULT_CHAIN.id],
    63	            arbitratorDisputeID: disputeID,
    64	            arbitrableAddress: arbitrableAddress,
    65	            arbitrableChainID: disputeData.dispute?.arbitrableChainId,
    66	            graphApiKey: import.meta.env.REACT_APP_GRAPH_API_KEY,
    67	            alchemyApiKey: import.meta.env.ALCHEMY_API_KEY,
    68	          };
    69	
    70	          const data = dataMappings ? await executeActions(JSON.parse(dataMappings), initialContext) : {};
    71	          const disputeDetails = populateTemplate(templateData, data);
    72	
    73	          return disputeDetails;
    74	        } catch (error) {
    75	          console.warn({ error });
    76	          if (error instanceof HttpRequestError || error instanceof RpcError) {
    77	            debounceErrorToast("RPC failed!, Please avoid voting.");
    78	            throw Error;
    79	          }
    80	
    81	          return {} as DisputeDetails;
    82	        }
    83	      } else throw Error;
    84	    },
    85	  });
    86	};
