  1	import React, { useMemo, createContext, useContext, useState } from "react";
  2	
  3	import { useParams } from "react-router-dom";
  4	import { Address } from "viem";
  5	
  6	import { Answer, DisputeDetails } from "@kleros/kleros-sdk";
  7	
  8	import { ONE_BASIS_POINT } from "consts/index";
  9	import { Periods } from "consts/periods";
 10	import { usePopulatedDisputeData } from "hooks/queries/usePopulatedDisputeData";
 11	import { useCountdown } from "hooks/useCountdown";
 12	import { getLocalRounds } from "utils/getLocalRounds";
 13	import { isUndefined } from "utils/index";
 14	
 15	import { useAppealCost } from "queries/useAppealCost";
 16	import { useClassicAppealQuery, ClassicAppealQuery } from "queries/useClassicAppealQuery";
 17	import { useDisputeKitMultipliers } from "queries/useDisputeKitMultipliers";
 18	
 19	type Option = Answer & { paidFee?: string; funded?: boolean };
 20	interface ICountdownContext {
 21	  loserSideCountdown?: number;
 22	  winnerSideCountdown?: number;
 23	  isLoading?: boolean;
 24	}
 25	
 26	const CountdownContext = createContext<ICountdownContext>({});
 27	
 28	const OptionsContext = createContext<Option[] | undefined>(undefined);
 29	
 30	interface ISelectedOptionContext {
 31	  selectedOption: Option | undefined;
 32	  setSelectedOption: (arg0: Option) => void;
 33	}
 34	const SelectedOptionContext = createContext<ISelectedOptionContext>({
 35	  selectedOption: undefined,
 36	
 37	  setSelectedOption: () => {},
 38	});
 39	
 40	interface IFundingContext {
 41	  winningChoice: string | undefined;
 42	  loserRequiredFunding: bigint | undefined;
 43	  winnerRequiredFunding: bigint | undefined;
 44	  fundedChoices: string[] | undefined;
 45	}
 46	
 47	const FundingContext = createContext<IFundingContext>({
 48	  winningChoice: undefined,
 49	  loserRequiredFunding: undefined,
 50	  winnerRequiredFunding: undefined,
 51	  fundedChoices: undefined,
 52	});
 53	
 54	export const ClassicAppealProvider: React.FC<{
 55	  children: React.ReactNode;
 56	}> = ({ children }) => {
 57	  const { id } = useParams();
 58	  const { data } = useClassicAppealQuery(id);
 59	  const dispute = data?.dispute;
 60	  const winningChoice = getWinningChoice(data?.dispute);
 61	  const { data: appealCost } = useAppealCost(id);
 62	  const arbitrable = data?.dispute?.arbitrated.id;
 63	  const { data: disputeDetails } = usePopulatedDisputeData(id, arbitrable as Address);
 64	  const { data: multipliers } = useDisputeKitMultipliers(data?.dispute?.currentRound?.disputeKit?.address as Address);
 65	
 66	  const [selectedOption, setSelectedOption] = useState<Option>();
 67	
 68	  const options = useMemo(() => getOptions(disputeDetails, data?.dispute), [disputeDetails, data]);
 69	
 70	  const loserSideCountdown = useLoserSideCountdown(
 71	    dispute?.lastPeriodChange,
 72	    dispute?.currentRound.timesPerPeriod[Periods.appeal],
 73	    multipliers?.loser_appeal_period_multiplier.toString()
 74	  );
 75	
 76	  const winnerSideCountdown = useWinnerSideCountdown(
 77	    dispute?.lastPeriodChange,
 78	    dispute?.currentRound.timesPerPeriod[Periods.appeal]
 79	  );
 80	
 81	  const isLoading = useMemo(() => isUndefined(dispute) || isUndefined(multipliers), [dispute, multipliers]);
 82	
 83	  const { loserRequiredFunding, winnerRequiredFunding } = useMemo(
 84	    () => ({
 85	      loserRequiredFunding: getRequiredFunding(appealCost, multipliers?.loser_stake_multiplier),
 86	      winnerRequiredFunding: getRequiredFunding(appealCost, multipliers?.winner_stake_multiplier),
 87	    }),
 88	    [appealCost, multipliers]
 89	  );
 90	  const fundedChoices = getFundedChoices(data?.dispute);
 91	
 92	  return (
 93	    <CountdownContext.Provider
 94	      value={useMemo(
 95	        () => ({ loserSideCountdown, winnerSideCountdown, isLoading }),
 96	        [loserSideCountdown, winnerSideCountdown, isLoading]
 97	      )}
 98	    >
 99	      <SelectedOptionContext.Provider
100	        value={useMemo(() => ({ selectedOption, setSelectedOption }), [selectedOption, setSelectedOption])}
101	      >
102	        <FundingContext.Provider
103	          value={useMemo(
104	            () => ({
105	              winningChoice,
106	              loserRequiredFunding,
107	              winnerRequiredFunding,
108	              fundedChoices,
109	            }),
110	            [winningChoice, loserRequiredFunding, winnerRequiredFunding, fundedChoices]
111	          )}
112	        >
113	          <OptionsContext.Provider value={options}>{children}</OptionsContext.Provider>
114	        </FundingContext.Provider>
115	      </SelectedOptionContext.Provider>
116	    </CountdownContext.Provider>
117	  );
118	};
119	
120	export const useCountdownContext = () => useContext(CountdownContext);
121	export const useSelectedOptionContext = () => useContext(SelectedOptionContext);
122	export const useFundingContext = () => useContext(FundingContext);
123	export const useOptionsContext = () => useContext(OptionsContext);
124	
125	const getCurrentLocalRound = (dispute?: ClassicAppealQuery["dispute"]) => {
126	  if (!dispute) return undefined;
127	
128	  const period = dispute.period;
129	  const lastDisputeKitDispute = dispute.disputeKitDispute[dispute.disputeKitDispute.length - 1];
130	  if (isUndefined(lastDisputeKitDispute)) return undefined;
131	
132	  const currentLocalRoundIndex = lastDisputeKitDispute?.currentLocalRoundIndex;
133	  if (isUndefined(currentLocalRoundIndex)) return undefined;
134	
135	  const adjustedRoundIndex = ["appeal", "execution"].includes(period)
136	    ? Number(BigInt(currentLocalRoundIndex))
137	    : Number(BigInt(currentLocalRoundIndex) - 1n);
138	
139	  return getLocalRounds(dispute.disputeKitDispute)[adjustedRoundIndex];
140	};
141	
142	const getOptions = (dispute?: DisputeDetails, classicDispute?: ClassicAppealQuery["dispute"]) => {
143	  if (!dispute || Object.keys(dispute).length === 0) return [];
144	  const currentLocalRound = getCurrentLocalRound(classicDispute);
145	  const classicAnswers = currentLocalRound?.answers;
146	
147	  const options = dispute.answers?.map((answer) => {
148	    const classicAnswer = classicAnswers?.find((classicAnswer) => BigInt(classicAnswer.answerId) == BigInt(answer.id));
149	    // converting hexadecimal id to stringified bigint to match id fomr subgraph
150	    return {
151	      ...answer,
152	      id: BigInt(answer.id).toString(),
153	      paidFee: classicAnswer?.paidFee ?? "0",
154	      funded: classicAnswer?.funded ?? false,
155	    };
156	  });
157	  return options;
158	};
159	
160	const getFundedChoices = (dispute?: ClassicAppealQuery["dispute"]) => {
161	  const currentLocalRound = getCurrentLocalRound(dispute);
162	  return currentLocalRound?.fundedChoices;
163	};
164	
165	const getWinningChoice = (dispute?: ClassicAppealQuery["dispute"]) => {
166	  const currentLocalRound = getCurrentLocalRound(dispute);
167	  return currentLocalRound?.winningChoice;
168	};
169	
170	export const getRequiredFunding = (appealCost = 0n, stake_multiplier = 0n): bigint =>
171	  appealCost + (stake_multiplier * appealCost) / ONE_BASIS_POINT;
172	
173	function useLoserSideCountdown(lastPeriodChange = "0", appealPeriodDuration = "0", loserTimeMultiplier = "0") {
174	  const deadline = useMemo(
175	    () => getDeadline(lastPeriodChange, appealPeriodDuration, loserTimeMultiplier),
176	    [lastPeriodChange, appealPeriodDuration, loserTimeMultiplier]
177	  );
178	  return useCountdown(deadline);
179	}
180	
181	function useWinnerSideCountdown(lastPeriodChange = "0", appealPeriodDuration = "0") {
182	  const deadline = useMemo(
183	    () => Number(BigInt(lastPeriodChange) + BigInt(appealPeriodDuration)),
184	    [lastPeriodChange, appealPeriodDuration]
185	  );
186	  return useCountdown(deadline);
187	}
188	
189	const getDeadline = (lastPeriodChange: string, appealPeriodDuration: string, loserTimeMultiplier: string): number => {
190	  const parsedLastPeriodChange = BigInt(lastPeriodChange);
