    89	  const [debouncedAmount, setDebouncedAmount] = useState<NumberString>("0");
    90	  useDebounce(() => setDebouncedAmount(amount), 500, [amount]);
    91	
    92	  const parsedAmount = useParsedAmount(debouncedAmount as NumberString);
    93	
    94	  const insufficientBalance = useMemo(() => {
    95	    return balance && balance.value < parsedAmount;
    96	  }, [balance, parsedAmount]);
    97	
    98	  const { mutateAsync: fundAppeal, isPending } = useFundAppeal(() => {
    99	    setIsOpen(true);
   100	  });
   101	
   102	  const isFundDisabled = useMemo(
   103	    () =>
   104	      isDisconnected ||
   105	      !balance ||
   106	      insufficientBalance ||
   107	      parsedAmount <= 0n ||
   108	      isPending ||
   109	      isUndefined(selectedOption?.id),
   110	    [isDisconnected, balance, insufficientBalance, parsedAmount, isPending, selectedOption]
   111	  );
   112	
   113	  const handleAppeal = useCallback(async () => {
   114	    if (isUndefined(disputeId) || isUndefined(selectedOption?.id)) return;
   115	
   116	    await fundAppeal({
   117	      disputeId: BigInt(disputeId),
   118	      choice: BigInt(selectedOption.id),
   119	      fundAmount: parsedAmount,
   120	      disputeKitId,
   121	    });
   122	  }, [fundAppeal, disputeId, selectedOption, parsedAmount, disputeKitId]);
   123	
   124	  return needFund ? (
