    57	  const [displayRipple, setDisplayRipple] = useState(false);
    59	  const { data } = useDisputeDetailsQuery(id);
    60	  const dispute = data?.dispute;
    62	  // using interval here instead of useMemo with dispute, since we can't tell when period has timed out,
    63	  // we can use useCountdown, but that would trigger the update every 1 sec. so this is ideal.
    64	  useEffect(() => {
    65	    const rippleCheck = () => {
    66	      if (!dispute) return;
    68	      const period = Periods[dispute?.period] ?? 0;
    69	      const now = Date.now() / 1000;
    71	      if (
    72	        (dispute.period !== Period.Execution &&
    73	          now > parseInt(dispute.lastPeriodChange) + parseInt(dispute.currentRound.timesPerPeriod[period])) ||
    74	        (dispute.period === Period.Execution && !dispute.ruled)
    75	      ) {
    76	        setDisplayRipple(true);
    77	        return;
    78	      }
    80	      setDisplayRipple(false);
    81	    };
    83	    // initial check
    84	    rippleCheck();
    86	    const intervalId = setInterval(() => {
    87	      if (!dispute) return;
    89	      if (dispute.ruled) {
    90	        clearInterval(intervalId);
    91	        return;
    92	      }
    93	      rippleCheck();
    94	    }, 5000);
    96	    return () => clearInterval(intervalId);
    97	  }, [dispute]);
